BANKS = {
 'cs': 'Exam by topic/Consolidated Statements/Consolidated Statements Exam Bank.md',
 'fr': 'Exam by topic/Financial Reporting/Financial Reporting Exam Bank.md',
 'au': 'Exam by topic/Auditing/Auditing Exam Bank.md',
}
questions = []
for prefix, filename in BANKS.items():
 text = (ROOT / filename).read_text()
 starts = list(re.finditer(r'^\*\*(\d+(?:\.\d+)?)[.]?(?=[ .])', text, re.M))
 for index, match in enumerate(starts, 1):
  end = starts[index].start() if index < len(starts) else len(text)
  raw = text[match.start():end].strip()
  # Headings and shared scenarios between questions belong to the next question.
  stop = re.search(r'^#{2,3} ', raw, re.M)
  if stop: raw = raw[:stop.start()].strip()
  option_start = re.search(r'^- [a-d]\. ', raw, re.M)
  answer_start = re.search(r'^- \*\*Your answer:', raw, re.M)
  question_end = option_start.start() if option_start else answer_start.start() if answer_start else len(raw)
  wording = raw[:question_end].strip()
  options = [{'id':m.group(1), 'text':m.group(2).strip()} for m in re.finditer(r'^- ([a-d])\. (.+)$', raw, re.M)]
  recorded = re.search(r'^- \*\*Your answer:\*\* (.+)$', raw, re.M)
  marks = re.search(r'\((\d+) mark', wording)
  headings = re.findall(r'^#{2,3} (.+)$', text[:match.start()], re.M)
  topic = {'cs':'Consolidated Statements','fr':'Financial Reporting','au':'Auditing'}[prefix]
  difficulty = 'Easy'
  if prefix == 'cs': difficulty = [h for h in headings if h in ['Easy','Medium','Hard']][-1]
  if not options: options = [{'id':'a','text':'True'},{'id':'b','text':'False'}]
  q = {'id':f'{prefix}-{index:02}', 'origin':'original', 'topic':topic, 'subtopic':'Pending review', 'difficulty':difficulty,
       'type':'true-false' if len(options)==2 and options[0]['text']=='True' else 'single-choice',
       'marks':int(marks.group(1)) if marks else None, 'prompt':re.sub(r'\*\*|\*', '', wording), 'scenario':'', 'assumptions':[],
       'options':options, 'correctOptionId':None, 'explanation':'', 'workedCalculation':'', 'evidence':[],
       'status':'review', 'reviewReason':'Not yet validated', 'changes':[],
       'source':{'path':filename,'heading':headings[-1] if headings else '', 'number':match.group(1),'line':text[:match.start()].count('\n')+1},
       'original':{'wording':wording,'options':[dict(o) for o in options] if option_start else [], 'raw':raw,'recordedStudentAnswer':recorded.group(1) if recorded else None}}
  questions.append(q)

