def intro(prefix, heading):
 text = (ROOT / BANKS[prefix]).read_text()
 part = text.split(heading+'\n',1)[1]
 return part.split('**',1)[0].strip()
def context(ids, scenario):
 for ident in ids.split():
  by_id[ident]['scenario']=scenario
  by_id[ident]['original']['scenario']=scenario
