def change(q, text): q['changes'].append(text)
def assume(q, *texts):
 q['assumptions'].extend(texts)
 if q['origin']=='original': change(q,'Added explicit study assumptions: '+' '.join(texts))
def validate(ident, key, subtopic, evidence, rule, feedback, calc='', check=None, difficulty=None):
 q=by_id[ident]
 assert len(feedback)==len(q['options']), ident
 q.update(correctOptionId=key,subtopic=subtopic,status='validated',reviewReason='',explanation=rule,workedCalculation=calc,evidence=[E[e] for e in evidence.split()])
 if difficulty: q['difficulty']=difficulty
 if check: q['calculationCheck']=check
 for o,(reason,tag) in zip(q['options'],feedback):
  o.update(explanation=reason,misconception=None if o['id']==key else tag)
 return q

def review(ident, reason, evidence):
 q=by_id[ident]; q['reviewReason']=reason; q['evidence']=[E[e] for e in evidence.split()]; q['subtopic']=evidence.split()[0].title()

