def generated(ident, topic, subtopic, difficulty, prompt, assumptions, opts, key, rule, feedback, calc='', check=None, evidence='', targets=()):
 q={'id':ident,'origin':'generated','topic':topic,'subtopic':subtopic,'difficulty':difficulty,'type':'true-false' if opts==['True','False'] else 'single-choice','marks':None,
    'prompt':prompt,'scenario':'','assumptions':[assumptions],'options':[{'id':chr(97+i),'text':v} for i,v in enumerate(opts)],'source':{'path':'Original study question','heading':subtopic,'number':ident,'line':None},'original':None,'changes':[], 'targets':list(targets)}
 questions.append(q);by_id[ident]=q
 validate(ident,key,subtopic,evidence,rule,feedback,calc,check)
 return q

def eq(ident,diff,prompt,opts,key,fb,inputs=None,val=None,calc=''):
 return generated(ident,'Consolidated Statements','Equity method',diff,prompt,EQ,opts,key,'Initially record cost; add the investor’s share of adjusted profit, subtract distributions and acquisition-uplift depreciation.',fb,calc,{'kind':'equity','inputs':inputs,'expected':val,'unit':'CHF'} if inputs else None,'equity',('equity-ignore-dividends','equity-dividend-income','equity-profit-direction','equity-initial-cost','equity-ignore-reserves','equity-ignore-profit'))
eq('eq-01','Easy','An associate pays a CHF 24,000 dividend in total. The investor owns 25%. What happens to its equity-method investment?', ['Increase by CHF 6,000','Decrease by CHF 6,000','Decrease by CHF 24,000','No change'],'b', [('A distribution reduces the investment; it is not extra equity income.','equity-dividend-income'),('The investor’s share of the distribution is CHF 6,000.',None),('Only the investor’s 25% share reduces this investment.','equity-whole-dividend'),('Cash received is accompanied by a reduction of investment.','equity-ignore-dividends')],{'opening':0,'profit':0,'dividends':24000,'share':.25,'uplift':0,'life':1},-6000,'25% × CHF 24,000 = CHF 6,000 reduction (a movement, not a negative closing balance).')
eq('eq-02','Medium','Opening investment is CHF 180,000. The 40%-owned associate earns CHF 55,000 and distributes CHF 20,000. What is the closing investment?', ['CHF 202,000','CHF 194,000','CHF 166,000','CHF 188,000'],'b', [('202,000 ignores distributions.','equity-ignore-dividends'),('180,000 + 22,000 − 8,000 = 194,000.',None),('166,000 reverses the profit movement.','equity-profit-direction'),('188,000 adds the dividend instead of the net profit share.','equity-dividend-income')],{'opening':180000,'profit':55000,'dividends':20000,'share':.4,'uplift':0,'life':1},194000,'180,000 + 40% × 55,000 − 40% × 20,000 = CHF 194,000.')
eq('eq-03','Medium','A 30%-owned associate incurs a CHF 60,000 loss and pays CHF 10,000 dividends. Opening investment is CHF 150,000. What is the closing balance?', ['CHF 135,000','CHF 168,000','CHF 132,000','CHF 129,000'],'d', [('135,000 adds the dividend to the loss movement.','equity-dividend-income'),('168,000 treats the loss as a profit and ignores dividends.','equity-profit-direction'),('132,000 ignores dividends.','equity-ignore-dividends'),('150,000 − 18,000 − 3,000 = 129,000.',None)],{'opening':150000,'profit':-60000,'dividends':10000,'share':.3,'uplift':0,'life':1},129000,'150,000 + 30% × (−60,000) − 30% × 10,000 = CHF 129,000.')
eq('eq-04','Hard','An investor pays CHF 360,000 for a 30% associate on 1 January. A CHF 80,000 total machine fair-value uplift has four years remaining life. The associate earns CHF 100,000 before uplift depreciation and pays CHF 40,000 dividends. What is the year-end investment? Ignore tax on the uplift.', ['CHF 384,000','CHF 378,000','CHF 372,000','CHF 358,000'],'c', [('384,000 omits dividends but deducts uplift depreciation.','equity-ignore-dividends'),('378,000 ignores uplift depreciation.','equity-ignore-reserves'),('360,000 + 30,000 − 12,000 − 6,000 = 372,000.',None),('358,000 deducts the whole uplift depreciation rather than 30%.','equity-whole-reserves')],{'opening':360000,'profit':100000,'dividends':40000,'share':.3,'uplift':80000,'life':4},372000,'Uplift depreciation = 80,000 / 4 = 20,000 total; investor adjustment = 6,000. Closing = 360,000 + 30,000 − 12,000 − 6,000 = CHF 372,000.')
eq('eq-05','Easy','An investor pays CHF 275,000 for a 25% associate. Its acquired share of book equity is CHF 210,000 and of machine uplift is CHF 25,000. At what amount is the investment initially recorded?', ['CHF 210,000','CHF 235,000','CHF 250,000','CHF 275,000'],'d', [('210,000 omits uplift and goodwill components.','equity-initial-cost'),('235,000 excludes the residual goodwill component.','equity-initial-cost'),('250,000 subtracts the uplift from acquisition cost.','equity-initial-cost'),('Initial measurement is the full cost of 275,000.',None)],None,None,'Supporting allocation: 210,000 book equity + 25,000 uplift + 40,000 goodwill = CHF 275,000 initial cost.')
eq('eq-06','Hard','A 20%-owned associate pays CHF 30,000 dividends from prior-year reserves in the current year, earns CHF 70,000 current profit, and has CHF 10,000 current additional fair-value depreciation. Opening investment is CHF 95,000. What is the closing investment?', ['CHF 101,000','CHF 109,000','CHF 107,000','CHF 125,000'],'a', [('95,000 + 14,000 − 6,000 − 2,000 = 101,000.',None),('109,000 ignores the paid dividend and additional depreciation.','equity-ignore-dividends'),('107,000 deducts additional depreciation but omits the dividend.','equity-ignore-dividends'),('125,000 adds all of the associate’s net movement rather than 20%.','equity-whole-profit')],{'opening':95000,'profit':70000,'dividends':30000,'share':.2,'uplift':10000,'life':1},101000,'95,000 + 20% × (70,000 − 10,000) − 20% × 30,000 = CHF 101,000. Dividends reduce carrying amount even when funded from prior-year reserves.')

def imp(ident,diff,prompt,opts,key,fb,inputs=None,val=None,calc=''):
 return generated(ident,'Financial Reporting','Impairment',diff,prompt,IMP,opts,key,'Recoverable amount is the higher of value in use and fair value less disposal costs. Impairment is the positive excess of carrying amount over recoverable amount.',fb,calc,{'kind':'impairment','inputs':inputs,'expected':val,'unit':'CHF'} if inputs else None,'impairment',('impairment-use-minimum','impairment-v i u-only','impairment-disposal-costs','impairment-indicator','impairment-necessary-condition'))
imp('imp-01','Easy','Value in use is CHF 91,000 and fair value less costs of disposal is CHF 86,000. What is recoverable amount?', ['CHF 86,000','CHF 91,000','CHF 88,500','CHF 177,000'],'b', [('Use the higher, not lower, alternative.','impairment-use-minimum'),('Use of the asset offers the higher recoverable value.',None),('Recoverable amount is not an average.','impairment-average'),('Use and sale are alternatives, not additive recoveries.','impairment-add-values')],{'carrying':100000,'viu':91000,'fairValue':86000,'disposal':0,'measure':'recoverable'},91000,'max(91,000, 86,000) = CHF 91,000.')
imp('imp-02','Medium','A machine carries at CHF 120,000. Its VIU is CHF 93,000; fair value is CHF 104,000 and disposal costs CHF 7,000. What is the impairment loss?', ['CHF 16,000','CHF 27,000','CHF 23,000','CHF 30,000'],'c', [('16,000 ignores disposal costs.','impairment-disposal-costs'),('27,000 uses VIU even though net sale value is higher.','impairment-v i u-only'),('120,000 − max(93,000, 97,000) = 23,000.',None),('30,000 subtracts disposal costs from VIU as well.','impairment-costs-from-viu')],{'carrying':120000,'viu':93000,'fairValue':104000,'disposal':7000,'measure':'loss'},23000,'FVLCD = 104,000 − 7,000 = 97,000; RA = 97,000; loss = 120,000 − 97,000 = CHF 23,000.')
imp('imp-03','Medium','Carrying amount is CHF 75,000, VIU CHF 68,000, and FVLCD CHF 79,000. What impairment is recognized?', ['CHF 7,000 loss','No impairment','CHF 4,000 gain','CHF 11,000 loss'],'b', [('Low VIU alone does not require a loss when FVLCD supports carrying value.','impairment-v i u-only'),('Recoverable amount is above carrying amount.',None),('A cost-model impairment test does not automatically revalue the asset upward.','impairment-upward-gain'),('The two alternative recoveries are not separate losses.','impairment-add-values')],{'carrying':75000,'viu':68000,'fairValue':79000,'disposal':0,'measure':'loss'},0,'RA = max(68,000, 79,000) = 79,000; max(0, 75,000 − 79,000) = CHF 0.')
imp('imp-04','Hard','A machine cost CHF 240,000, with no residual value and six-year straight-line life. After two complete years it has VIU CHF 142,000, fair value CHF 151,000 and disposal costs CHF 4,000. What carrying amount remains after impairment?', ['CHF 142,000','CHF 147,000','CHF 160,000','CHF 151,000'],'b', [('142,000 ignores the higher net sale value.','impairment-v i u-only'),('RA is 147,000, below the pre-test 160,000.',None),('160,000 is before the 13,000 impairment.','impairment-no-loss'),('151,000 ignores disposal costs.','impairment-disposal-costs')],{'cost':240000,'life':6,'years':2,'viu':142000,'fairValue':151000,'disposal':4000,'measure':'closing'},147000,'Depreciation = 240,000 / 6 × 2 = 80,000. Pre-test carrying = 160,000. RA = max(142,000, 151,000 − 4,000) = 147,000. Loss = 13,000; closing = CHF 147,000.')
imp('imp-05','Easy','True or false: VIU below carrying amount is sufficient by itself to prove an impairment, even when FVLCD is above carrying amount.', ['True','False'],'b', [('The second recoverability alternative prevents this conclusion.','impairment-v i u-only'),('The higher FVLCD can support carrying amount.',None)])
imp('imp-06','Medium','A machine carries at CHF 48,000. VIU and FVLCD both equal CHF 42,000. Which pair is correct: impairment loss / closing carrying amount?', ['CHF 6,000 / CHF 42,000','CHF 12,000 / CHF 36,000','CHF 0 / CHF 48,000','CHF 42,000 / CHF 6,000'],'a', [('The single loss is 48,000 − 42,000.',None),('Do not count the same recoverability shortfall twice.','impairment-double-loss'),('Both recoverable alternatives are below carrying value.','impairment-no-loss'),('This swaps the loss and remaining asset.','impairment-loss-vs-value')],{'carrying':48000,'viu':42000,'fairValue':42000,'disposal':0,'measure':'loss'},6000,'RA = CHF 42,000; loss = 48,000 − 42,000 = CHF 6,000; closing = CHF 42,000.')

def audit(ident,diff,prompt,opts,key,fb):
 return generated(ident,'Auditing','Audit procedures',diff,prompt,AUD,opts,key,'Analytics evaluate relationships against expectations; tests of details inspect individual supporting evidence.',fb,evidence='procedures',targets=('audit-analytical-vs-details','audit-analytical-purpose','audit-analytical-phase'))
audit('audit-01','Easy','Which is an analytical procedure for sales?', ['Confirm a customer’s balance','Inspect one delivery note','Compare monthly margins with the prior year','Trace a receipt to a bank statement'],'c', [('Confirmation is direct balance evidence.','audit-analytical-vs-details'),('One document is transaction-specific evidence.','audit-analytical-vs-details'),('A margin trend evaluates a relationship.',None),('Tracing one receipt is a test of details.','audit-analytical-vs-details')])
audit('audit-02','Easy','Which is a test of details for receivables?', ['Compare debtor days year to year','Obtain confirmations from selected customers','Compare aging proportions with last year','Estimate collections from historical ratios'],'b', [('Debtor days is a ratio comparison.','audit-analytical-vs-details'),('Confirmations test specified balances directly.',None),('Aging proportions evaluate a relationship.','audit-analytical-vs-details'),('A ratio-based expectation is analytical.','audit-analytical-vs-details')])
audit('audit-03','Medium','Revenue rose 10%, receivables 45%. The auditor flags the discrepancy, then inspects selected overdue invoices and subsequent bank receipts. Which classification is correct?', ['Both steps are analytical','Both steps are tests of details','First details; then analytical','First analytical; then details'],'d', [('Inspecting selected invoices and receipts is a test of details.','audit-analytical-vs-details'),('The initial cross-account trend comparison is analytical.','audit-analytical-vs-details'),('This reverses the two types.','audit-analytical-vs-details'),('Trend evaluation precedes inspection of specific evidence.',None)])
audit('audit-04','Medium','The auditor builds an expected payroll expense using average headcount and average pay, then compares it with recorded payroll. How is this classified?', ['Analytical procedure','Test of individual balances','Physical inspection','External confirmation'],'a', [('An independent relationship-based expectation is analytical.',None),('No individual employee balance is directly tested here.','audit-analytical-vs-details'),('No tangible asset is inspected.','audit-procedure-type'),('No third party confirms a specified amount.','audit-procedure-type')])
audit('audit-05','Easy','True or false: An analytical procedure can be designed as a substantive audit procedure; “analytical” and “substantive” are not mutually exclusive.', ['True','False'],'a', [('A suitably reliable expectation can provide substantive evidence.',None),('Substantive procedures include analytics as well as tests of details.','audit-analytical-vs-substantive')])
audit('audit-06','Hard','Inventory turnover fell from 6 to 3. The auditor investigates the ratio change, inspects selected aged stock, and checks supplier invoices for those items. Which statement best describes the evidence?', ['The ratio alone establishes exact stock value','All three actions are external confirmations','The ratio is analytical; inspection and invoices test details','Invoice checks are analytical because they contain numbers'],'c', [('An unusual ratio identifies risk; it does not establish each item’s value.','audit-analytics-conclusive'),('Neither ratio analysis nor physical inspection is a confirmation.','audit-procedure-type'),('Relationship analysis and item-specific evidence have distinct roles.',None),('Using numbers does not make direct evidence analytical.','audit-analytical-vs-details')])

def acq(ident,diff,prompt,opts,key,fb,inputs,val,kind,calc,tax=False):
 return generated(ident,'Consolidated Statements','Acquisition accounting',diff,prompt,ACQ+(' Recognize the specified DTL on the uplift.' if tax else ' Ignore all deferred tax on acquisition uplifts.'),opts,key,'Partial goodwill uses the parent’s share of fair-value identifiable net assets; NCI uses the outside share. Recognized acquisition deferred tax reduces those net assets.',fb,calc,{'kind':kind,'inputs':inputs,'expected':val,'unit':'CHF'},'acquisition tax' if tax else 'acquisition',('goodwill-ignore-reserves','nci-ignore-reserves','nci-all-reserves','nci-purchase-price','goodwill-wrong-share','tax-rate-omitted'))
acq('acq-01','Medium','A parent pays CHF 720,000 for 75% of a target with CHF 600,000 book equity and CHF 120,000 machine uplift. What is partial goodwill?', ['CHF 180,000','CHF 270,000','CHF 0','CHF 540,000'],'a', [('720,000 − 75% × 720,000 = 180,000.',None),('270,000 ignores hidden reserves.','goodwill-ignore-reserves'),('Cost exceeds the acquired share, even though it equals all net assets.','goodwill-whole-assets'),('540,000 is acquired identifiable net assets, not goodwill.','goodwill-net-assets')],{'cost':720000,'equity':600000,'uplift':120000,'share':.75},180000,'goodwill','Fair-value net assets = 600,000 + 120,000 = 720,000. Goodwill = 720,000 − 75% × 720,000 = CHF 180,000.')
acq('acq-02','Medium','A parent acquires 70% of a target. Book equity is CHF 420,000 and hidden reserves CHF 80,000. What is acquisition-date NCI?', ['CHF 126,000','CHF 150,000','CHF 206,000','CHF 350,000'],'b', [('126,000 omits NCI’s share of hidden reserves.','nci-ignore-reserves'),('30% × 500,000 = 150,000.',None),('206,000 assigns the full uplift to NCI.','nci-all-reserves'),('350,000 is the parent’s share.','nci-parent-share')],{'equity':420000,'uplift':80000,'share':.7},150000,'nci','NCI = 30% × (420,000 + 80,000) = CHF 150,000.')
acq('acq-03','Easy','An acquisition’s total fair-value net assets are CHF 840,000. The parent acquires 60%, paying exactly its proportionate net-asset value. How much goodwill arises?', ['CHF 336,000','CHF 504,000','CHF 840,000','CHF 0'],'d', [('336,000 is NCI, not goodwill.','goodwill-nci-confusion'),('504,000 is the acquired net-asset value.','goodwill-net-assets'),('840,000 is all net assets.','goodwill-whole-assets'),('Price equals the acquired share, so the residual is zero.',None)],{'equity':840000,'uplift':0,'share':.6,'cost':504000},0,'goodwill','Cost = 60% × 840,000 = 504,000; goodwill = 504,000 − 504,000 = CHF 0.')
acq('acq-04','Hard','A parent pays CHF 960,000 for 80%. Target book equity is CHF 700,000; a machine’s fair-value uplift is CHF 200,000 and its tax base is unchanged. Tax rate is 25%. What partial goodwill is recognized?', ['CHF 240,000','CHF 280,000','CHF 210,000','CHF 110,000'],'b', [('240,000 ignores the uplift’s deferred tax.','acquisition-ignore-tax'),('DTL 50,000 reduces net assets to 850,000; goodwill is 280,000.',None),('210,000 adds the DTL outside the ownership allocation incorrectly.','acquisition-tax-allocation'),('110,000 subtracts all net assets instead of the acquired 80%.','goodwill-whole-assets')],{'equity':700000,'uplift':200000,'share':.8,'cost':960000,'taxRate':.25},280000,'goodwill','DTL = 200,000 × 25% = 50,000. FV net assets = 700,000 + 200,000 − 50,000 = 850,000. Goodwill = 960,000 − 80% × 850,000 = CHF 280,000.',True)
acq('acq-05','Hard','An investor acquires 65% of a target with CHF 1,000,000 book equity and CHF 240,000 machine uplift. Tax base is unchanged and tax rate is 20%. What NCI is recognized at acquisition?', ['CHF 434,000','CHF 784,000','CHF 417,200','CHF 350,000'],'c', [('434,000 ignores the uplift DTL.','acquisition-ignore-tax'),('784,000 is not the outsiders’ 35% share.','nci-wrong-share'),('35% × (1,000,000 + 240,000 − 48,000) = 417,200.',None),('350,000 ignores both uplift and related tax.','nci-ignore-reserves')],{'equity':1000000,'uplift':240000,'share':.65,'taxRate':.2},417200,'nci','Uplift DTL = 48,000. Net assets = 1,192,000. NCI = 35% × 1,192,000 = CHF 417,200.',True)
acq('acq-06','Easy','A target has CHF 900,000 fair-value net assets. The parent owns 80%. Under partial goodwill, does the price paid determine NCI’s acquisition-date amount?', ['Yes; NCI is 20% of price','Yes; NCI is 80% of price','No; NCI is CHF 180,000','No; NCI is CHF 720,000'],'c', [('Partial-goodwill NCI is not a share of parent consideration.','nci-purchase-price'),('This uses parent ownership and the wrong measurement base.','nci-parent-share'),('NCI is 20% of fair-value net assets.',None),('720,000 is the parent share, not NCI.','nci-parent-share')],{'equity':900000,'uplift':0,'share':.8},180000,'nci','NCI = (1 − 80%) × CHF 900,000 = CHF 180,000, independent of the parent price under this method.')

def tax(ident,diff,prompt,opts,key,fb,inputs=None,val=None,kind='asset-tax',calc=''):
 return generated(ident,'Financial Reporting','Deferred taxes',diff,prompt,TAX,opts,key,'Compare carrying amount with tax base. For ordinary assets, carrying amount above tax base gives a DTL; below tax base gives a DTA when recoverable. Multiply the temporary difference by the tax rate.',fb,calc,{'kind':kind,'inputs':inputs,'expected':val,'unit':'CHF'} if inputs else None,'tax',('tax-rate-omitted','tax-direction','tax-wrong-rate','tax-permanent-vs-temporary','tax-gross-balance','acquisition-ignore-tax'))
tax('tax-01','Easy','A machine’s book carrying amount is CHF 84,000 and tax base CHF 60,000. Rate is 20%. Which deferred tax balance arises?', ['CHF 24,000 DTL','CHF 4,800 DTA','CHF 4,800 DTL','CHF 16,800 DTL'],'c', [('24,000 is the temporary difference before tax.','tax-rate-omitted'),('Book amount exceeds tax base, creating future taxable amounts.','tax-direction'),('24,000 × 20% = 4,800 DTL.',None),('16,800 applies tax to the full carrying amount.','tax-gross-balance')],{'book':84000,'base':60000,'rate':.2},4800,calc='Difference = 84,000 − 60,000 = 24,000 taxable; deferred tax = 24,000 × 20% = CHF 4,800 DTL.')
tax('tax-02','Medium','Inventory cost CHF 90,000. Book reporting writes it down to CHF 54,000; tax permits a 20% cost write-down now and deducts the remainder on later sale. Tax rate is 15%. Which balance is recognized?', ['CHF 2,700 DTA','CHF 18,000 DTA','CHF 2,700 DTL','CHF 5,400 DTA'],'a', [('Tax base 72,000 exceeds book 54,000 by 18,000; tax effect 2,700.',None),('18,000 is the untaxed temporary difference.','tax-rate-omitted'),('Book below tax base creates future relief, not a tax burden.','tax-direction'),('5,400 taxes the entire book write-down rather than the book-tax difference.','tax-wrong-difference')],{'cost':90000,'book':54000,'taxWriteDown':.2,'rate':.15},2700,'inventory-tax','Tax base = 90,000 × 80% = 72,000. Deductible difference = 18,000. DTA = 18,000 × 15% = CHF 2,700.')
tax('tax-03','Easy','True or false: A CHF 40,000 taxable temporary difference at 12.5% produces a CHF 40,000 deferred tax liability.', ['True','False'],'b', [('The statement omits multiplication by the rate.','tax-rate-omitted'),('The DTL is CHF 5,000, not CHF 40,000.',None)],{'book':80000,'base':40000,'rate':.125},5000,calc='CHF 40,000 × 12.5% = CHF 5,000 DTL.')
tax('tax-04','Hard','Equipment costs CHF 250,000 on 1 January. IFRS uses five-year straight-line depreciation, zero residual; tax uses 40% declining balance. At the end of year one, with 18% tax, what deferred tax balance arises?', ['CHF 50,000 DTL','CHF 9,000 DTA','CHF 36,000 DTL','CHF 9,000 DTL'],'d', [('50,000 is the temporary difference before applying 18%.','tax-rate-omitted'),('Book 200,000 is higher than tax base 150,000: liability.','tax-direction'),('36,000 taxes the entire book carrying amount.','tax-gross-balance'),('50,000 × 18% = 9,000 DTL.',None)],{'cost':250000,'life':5,'taxDepreciation':.4,'rate':.18,'year':1},9000,'depreciation-tax','Book = 250,000 − 50,000 = 200,000. Tax base = 250,000 × 60% = 150,000. Difference = 50,000; DTL = CHF 9,000.')
tax('tax-05','Hard','Use a CHF 250,000 machine, five-year IFRS straight-line life, zero residual and 40% annual declining-balance tax depreciation. Tax rate is 18%. What is the deferred tax liability balance at the end of year two?', ['CHF 10,800','CHF 9,000','CHF 19,800','CHF 60,000'],'a', [('Book 150,000 less tax base 90,000 gives 60,000 × 18%.',None),('9,000 is the year-one balance, not year two.','tax-wrong-year'),('19,800 adds balance snapshots rather than reporting the closing balance.','tax-balance-vs-movement'),('60,000 is the temporary difference.','tax-rate-omitted')],{'cost':250000,'life':5,'taxDepreciation':.4,'rate':.18,'year':2},10800,'depreciation-tax','Book = 250,000 × 3/5 = 150,000. Tax base = 250,000 × 60%² = 90,000. Closing DTL = 60,000 × 18% = CHF 10,800 (increase from year one is 1,800).')
tax('tax-06','Medium','An asset is CHF 66,000 in IFRS books and CHF 81,000 for tax. The difference reverses on disposal. At 16%, what deferred tax balance is recognized?', ['CHF 15,000 DTA','CHF 2,400 DTL','CHF 2,400 DTA','CHF 12,960 DTA'],'c', [('15,000 is the deductible temporary difference, before tax.','tax-rate-omitted'),('A higher tax base gives future tax relief.','tax-direction'),('15,000 × 16% = 2,400 DTA.',None),('12,960 taxes the whole tax base.','tax-gross-balance')],{'book':66000,'base':81000,'rate':.16},-2400,calc='Deductible difference = 81,000 − 66,000 = 15,000; DTA = 15,000 × 16% = CHF 2,400. Signed check uses DTA as negative tax liability.')
tax('tax-07','Easy','A CHF 12,000 fine is expensed in IFRS reporting and is permanently nondeductible for tax. Rate is 20%. What deferred tax arises solely from this expense?', ['CHF 2,400 DTA','CHF 2,400 DTL','CHF 12,000 DTA','No deferred tax'],'d', [('There is no future deduction to create an asset.','tax-permanent-vs-temporary'),('A permanent difference does not reverse into deferred tax.','tax-permanent-vs-temporary'),('Neither a future deduction nor a CHF 12,000 tax amount exists.','tax-rate-omitted'),('No reversing timing difference exists.',None)],None,None,calc='The fine is never deductible. This permanent difference affects current tax reconciliation; no deferred tax balance is recognized.')
tax('tax-08','Medium','A machine has a CHF 36,000 taxable temporary difference. The enacted tax rate when it reverses is 22%, although the current-year rate is 18%. Which DTL is measured?', ['CHF 6,480','CHF 7,920','CHF 36,000','CHF 1,440'],'b', [('6,480 uses today’s 18%, not the enacted reversal rate.','tax-wrong-rate'),('36,000 × 22% = 7,920.',None),('36,000 omits the tax rate.','tax-rate-omitted'),('1,440 is only the rate-change increment.','tax-balance-vs-movement')],{'book':100000,'base':64000,'rate':.22},7920,calc='DTL = CHF 36,000 × enacted reversal rate 22% = CHF 7,920.')
tax('tax-09','Hard','Inventory cost is CHF 160,000. Book write-down is 35% of cost, while tax allows only 25% now; the additional deduction is allowed on sale. At 19% tax, what DTA is recognized?', ['CHF 10,640','CHF 16,000','CHF 3,040','CHF 7,600'],'c', [('10,640 taxes the entire book write-down.','tax-wrong-difference'),('16,000 is the deductible difference before tax.','tax-rate-omitted'),('Tax base 120,000 minus book 104,000 gives 16,000 × 19%.',None),('7,600 taxes the entire allowed tax write-down.','tax-wrong-difference')],{'cost':160000,'book':104000,'taxWriteDown':.25,'rate':.19},3040,'inventory-tax','Book = 160,000 × 65% = 104,000. Tax base = 160,000 × 75% = 120,000. DTA = (120,000 − 104,000) × 19% = CHF 3,040.')
tax('tax-10','Easy','A machine’s book value and tax base both equal CHF 50,000. Tax rate is 24%. What deferred tax balance arises from this machine?', ['No deferred tax','CHF 12,000 DTL','CHF 12,000 DTA','CHF 50,000 DTL'],'a', [('The temporary difference is zero.',None),('12,000 taxes a gross balance rather than a difference.','tax-gross-balance'),('Equal values create no future differential tax relief.','tax-gross-balance'),('50,000 is neither a difference nor a tax amount.','tax-rate-omitted')],{'book':50000,'base':50000,'rate':.24},0,calc='(50,000 − 50,000) × 24% = CHF 0.')
tax('tax-11','Hard','A machine costs CHF 480,000 with six-year IFRS straight-line depreciation and zero residual. Tax grants a first-year deduction of 30% of cost. At year-end, rate 21%, what pair is correct: taxable difference / DTL?', ['CHF 64,000 / CHF 64,000','CHF 13,440 / CHF 64,000','CHF 64,000 / CHF 13,440','CHF 80,000 / CHF 16,800'],'c', [('The tax balance is the difference times 21%.','tax-rate-omitted'),('This reverses the difference and tax amount.','tax-difference-vs-amount'),('Book 400,000 minus tax base 336,000 gives 64,000 and DTL 13,440.',None),('80,000 is IFRS depreciation, not the book-tax difference.','tax-depreciation-vs-difference')],{'cost':480000,'life':6,'taxDepreciation':.3,'rate':.21,'year':1},13440,'depreciation-tax','Book depreciation = 80,000; tax depreciation = 144,000. Book = 400,000; tax base = 336,000. Taxable difference = 64,000; DTL = 64,000 × 21% = CHF 13,440.')
tax('tax-12','Medium','An asset has a CHF 28,000 deductible temporary difference. The tax rate is 17.5%; sufficient future taxable profit is probable. Which balance is recognized?', ['CHF 28,000 DTA','CHF 4,900 DTL','No balance','CHF 4,900 DTA'],'d', [('28,000 is the difference before tax.','tax-rate-omitted'),('A deductible difference creates future relief, hence an asset.','tax-direction'),('The stated probable profits support DTA recognition.','tax-dta-recognition'),('28,000 × 17.5% = 4,900 DTA.',None)],{'book':72000,'base':100000,'rate':.175},-4900,calc='DTA = CHF 28,000 × 17.5% = CHF 4,900; recognize because recovery is probable.')

by_id['eq-05']['calculationCheck']={'kind':'sum','inputs':{'values':[210000,25000,40000]},'expected':275000,'unit':'CHF'}

